def either_or(primary, fallback, fallback_includes=None):
    def validator(data):
        schema = primary
        if (
            isinstance(data, Mapping)
            and set(fallback_includes or []) & data.keys()
        ):
            schema = fallback
        return Schema(schema)(data)

    return validator


